{
  "application": "report-generation",
  "case_id": "case-active-satellites-orbit-catalog-en",
  "language": "en",
  "report": {
    "type": "analytics-report",
    "audience": "space-industry analyst or policy advisor",
    "tone": "analytical, data-forward, professional"
  },
  "brief": {
    "title": "Active Satellites in Earth Orbit — 2026 Catalog Analysis",
    "one_liner": "A comprehensive analytical report on the 14,875 active satellites currently orbiting Earth, examining constellation composition, orbital regime distribution, and key orbital characteristics.",
    "goal": "Provide the reader with a clear, data-driven picture of the current satellite population: who operates the most satellites, how they are distributed across orbital regimes (LEO/MEO/GEO/HEO), what the dominant orbital parameters look like, and what trends in launch activity and constellation growth can be inferred from the catalog."
  },
  "required_sections": [
    {
      "section_id": "overview",
      "title": "Catalog Overview & Key Figures",
      "objective": "Summarize the total satellite count, data freshness (EPOCH range), and high-level statistics such as mean motion, inclination, and eccentricity distributions."
    },
    {
      "section_id": "orbit-regime",
      "title": "Orbital Regime Classification",
      "objective": "Classify satellites into LEO, MEO, GEO, and HEO categories using MEAN_MOTION thresholds and present the count and share of each regime."
    },
    {
      "section_id": "constellation-analysis",
      "title": "Major Constellation & Operator Breakdown",
      "objective": "Identify the largest satellite constellations (e.g., Starlink, OneWeb, GPS) by parsing OBJECT_NAME prefixes, and quantify their share of the total population."
    },
    {
      "section_id": "launch-trends",
      "title": "Launch Year Trends",
      "objective": "Extract launch year from OBJECT_ID and analyze the historical growth curve of currently active satellites, highlighting recent acceleration."
    },
    {
      "section_id": "orbital-characteristics",
      "title": "Orbital Parameter Deep Dive",
      "objective": "Examine distributions of INCLINATION, ECCENTRICITY, and MEAN_MOTION to characterize the most common orbital shells and highlight outliers (e.g., highly eccentric or polar orbits)."
    },
    {
      "section_id": "conclusions",
      "title": "Key Takeaways & Outlook",
      "objective": "Synthesize findings into actionable insights regarding orbital congestion, constellation dominance, and implications for space sustainability."
    }
  ],
  "kpis": [
    {
      "name": "Total Active Satellites",
      "description": "Total number of active satellites in the catalog."
    },
    {
      "name": "LEO Share (%)",
      "description": "Percentage of satellites in Low Earth Orbit (MEAN_MOTION > 14 rev/day)."
    },
    {
      "name": "Starlink Constellation Size",
      "description": "Count of satellites whose OBJECT_NAME starts with 'STARLINK'."
    },
    {
      "name": "Median Inclination (degrees)",
      "description": "Median orbital inclination across all active satellites, indicating the most common orbital tilt."
    },
    {
      "name": "Satellites Launched Since 2020",
      "description": "Number of currently active satellites with a launch year of 2020 or later, derived from OBJECT_ID."
    }
  ],
  "analysis_dimensions": [
    "OBJECT_NAME",
    "OBJECT_ID",
    "MEAN_MOTION",
    "INCLINATION",
    "ECCENTRICITY"
  ]
}

