python3 << 'PYEOF'
import json

with open('/app/output/analysis_data.json', 'r') as f:
    d = json.load(f)

total = d['total']
leo_count = d['leo_count']
leo_pct = d['leo_pct']
starlink_count = d['starlink_count']
median_inc = d['median_inclination']
post2020 = d['post2020']
regime_counts = d['regime_counts']
constellation_top20 = d['constellation_top20']
yearly_data = d['yearly_data']
inc_bins = d['inclination_bins']
ecc_ranges = d['eccentricity_ranges']
mm_mean = d['mm_mean']
mm_median = d['mm_median']
epoch_min = d['epoch_min'][:10]
epoch_max = d['epoch_max'][:10]

post2020_pct = round(post2020 / total * 100, 1)
starlink_pct = round(starlink_count / total * 100, 1)
starlink_leo_pct = round(starlink_count / leo_count * 100, 1)
non_starlink = total - starlink_count

# Regime data for chart
regime_order = ['LEO', 'GEO', 'MEO', 'HEO', 'Sub-GEO/Other']
regime_labels = json.dumps(regime_order)
regime_values = json.dumps([regime_counts.get(r, 0) for r in regime_order])
regime_pcts = [round(regime_counts.get(r, 0) / total * 100, 1) for r in regime_order]

# Constellation data for chart (top 10 named + Other)
top10 = [(name, count) for name, count in constellation_top20 if name != 'Other'][:10]
other_count = total - sum(c for _, c in top10)
const_labels = json.dumps([name for name, _ in top10] + ['Other'])
const_values = json.dumps([count for _, count in top10] + [other_count])

# Launch trend data
launch_years = [y['year'] for y in yearly_data if y['year'] >= 1990]
launch_counts = [y['count'] for y in yearly_data if y['year'] >= 1990]
launch_cum = [y['cumulative'] for y in yearly_data if y['year'] >= 1990]

# Recent acceleration
launch_years_recent = [y['year'] for y in yearly_data if y['year'] >= 2015]
launch_counts_recent = [y['count'] for y in yearly_data if y['year'] >= 2015]

# Inclination data
inc_labels = [f"{int(k)}°" for k in sorted(inc_bins.keys(), key=int)]
inc_values = [inc_bins[k] for k in sorted(inc_bins.keys(), key=int)]

# Eccentricity data
ecc_labels = json.dumps(list(ecc_ranges.keys()))
ecc_values = json.dumps(list(ecc_ranges.values()))

# Build constellation table rows
const_table = ""
for i, (name, count) in enumerate(constellation_top20):
    if name == 'Other':
        continue
    pct = round(count / total * 100, 1)
    const_table += f"""<tr>
        <td style="font-weight:500">{i+1 if name != 'Other' else ''}</td>
        <td style="font-weight:600">{name}</td>
        <td style="text-align:right">{count:,}</td>
        <td style="text-align:right">{pct}%</td>
        <td><div style="background:#3b82f6;height:8px;border-radius:4px;width:{min(count/starlink_count*100, 100):.1f}%"></div></td>
    </tr>"""

# Regime table rows
regime_table = ""
for r in regime_order:
    cnt = regime_counts.get(r, 0)
    pct = round(cnt / total * 100, 1)
    regime_table += f"""<tr>
        <td style="font-weight:600">{r}</td>
        <td style="text-align:right">{cnt:,}</td>
        <td style="text-align:right">{pct}%</td>
    </tr>"""

# Year-over-year growth table (2018-2026)
yoy_table = ""
prev = None
for yd in yearly_data:
    if yd['year'] >= 2018:
        growth = ""
        if prev:
            if prev > 0:
                g = round((yd['count'] - prev) / prev * 100, 1)
                color = "#10b981" if g > 0 else "#ef4444"
                growth = f'<span style="color:{color}">{"+" if g > 0 else ""}{g}%</span>'
        yoy_table += f"""<tr>
            <td style="font-weight:600">{yd['year']}</td>
            <td style="text-align:right">{yd['count']:,}</td>
            <td style="text-align:right">{yd['cumulative']:,}</td>
            <td style="text-align:right">{growth}</td>
        </tr>"""
        prev = yd['count']

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #ffffff;
    --surface: #f8fafc;
    --border: #e2e8f0;
    --text: #1e293b;
    --text-secondary: #64748b;
    --accent: #3b82f6;
    --accent-dark: #1d4ed8;
    --success: #10b981;
    --warning: #f59e0b;
    --danger: #ef4444;
  }}
  * {{ margin:0; padding:0; box-sizing:border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    max-width: 1200px;
    margin: 0 auto;
    padding: 40px 24px;
  }}
  .header {{
    text-align: center;
    margin-bottom: 48px;
    padding-bottom: 32px;
    border-bottom: 2px solid var(--border);
  }}
  .header h1 {{
    font-size: 2rem;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 8px;
  }}
  .header .subtitle {{
    font-size: 1.1rem;
    color: var(--text-secondary);
  }}
  .header .meta {{
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-top: 12px;
  }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 48px;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    text-align: center;
  }}
  .kpi-card .kpi-value {{
    font-size: 2rem;
    font-weight: 700;
    color: var(--accent-dark);
    line-height: 1.2;
  }}
  .kpi-card .kpi-label {{
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-top: 4px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }}
  .section {{
    margin-bottom: 48px;
  }}
  .section h2 {{
    font-size: 1.4rem;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 8px;
    padding-bottom: 8px;
    border-bottom: 2px solid var(--accent);
    display: inline-block;
  }}
  .section .section-desc {{
    color: var(--text-secondary);
    margin-bottom: 24px;
    font-size: 0.95rem;
  }}
  .chart-container {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 24px;
  }}
  .chart-container h3 {{
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: 16px;
    color: var(--text);
  }}
  .chart-wrap {{
    position: relative;
    width: 100%;
  }}
  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }}
  @media (max-width: 768px) {{
    .two-col {{ grid-template-columns: 1fr; }}
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
  }}
  table th {{
    text-align: left;
    padding: 10px 12px;
    border-bottom: 2px solid var(--border);
    color: var(--text-secondary);
    font-weight: 600;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }}
  table td {{
    padding: 8px 12px;
    border-bottom: 1px solid var(--border);
  }}
  table tr:last-child td {{ border-bottom: none; }}
  table tr:hover {{ background: rgba(59,130,246,0.04); }}
  .callout {{
    background: #eff6ff;
    border-left: 4px solid var(--accent);
    border-radius: 0 8px 8px 0;
    padding: 16px 20px;
    margin: 20px 0;
    font-size: 0.95rem;
  }}
  .callout strong {{ color: var(--accent-dark); }}
  .methodology {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px 20px;
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 20px;
  }}
  .methodology strong {{ color: var(--text); }}
  .insight {{ 
    color: var(--text-secondary); 
    font-size: 0.93rem; 
    margin-top: 12px;
    line-height: 1.6;
  }}
  .footer {{
    text-align: center;
    padding-top: 32px;
    border-top: 1px solid var(--border);
    color: var(--text-secondary);
    font-size: 0.8rem;
  }}
  .highlight {{ color: var(--accent-dark); font-weight: 600; }}
</style>
</head>
<body>

<div class="header">
  <h1>Active Satellites in Earth Orbit</h1>
  <div class="subtitle">2026 Catalog Analysis — {total:,} Active Spacecraft</div>
  <div class="meta">Data: CelesTrak / NORAD TLE Catalog &bull; Epoch window: {epoch_min} to {epoch_max} &bull; Report generated: 2026-04-24</div>
</div>

<!-- ===== KPI BLOCK ===== -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-value">{total:,}</div>
    <div class="kpi-label">Total Active Satellites</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{leo_pct}%</div>
    <div class="kpi-label">LEO Share</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{starlink_count:,}</div>
    <div class="kpi-label">Starlink Constellation</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{median_inc}&deg;</div>
    <div class="kpi-label">Median Inclination</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{post2020:,}</div>
    <div class="kpi-label">Launched Since 2020</div>
  </div>
</div>

<!-- ===== SECTION 1: OVERVIEW ===== -->
<div class="section" id="overview">
  <h2>Catalog Overview &amp; Key Figures</h2>
  <p class="section-desc">The CelesTrak active-satellite catalog contains <strong>{total:,}</strong> operational spacecraft as of late March 2026. Epoch timestamps range from {epoch_min} to {epoch_max}, confirming high data freshness across the catalog.</p>

  <div class="callout">
    <strong>Headline:</strong> {post2020_pct}% of all active satellites ({post2020:,} of {total:,}) were launched in 2020 or later. A single operator — SpaceX's Starlink — accounts for {starlink_pct}% of the entire catalog ({starlink_count:,} satellites), fundamentally reshaping the statistical profile of the orbital environment.
  </div>

  <div class="two-col">
    <div>
      <table>
        <tr><th colspan="2">Catalog Statistics</th></tr>
        <tr><td>Total active satellites</td><td style="text-align:right;font-weight:600">{total:,}</td></tr>
        <tr><td>Mean MEAN_MOTION</td><td style="text-align:right">{mm_mean} rev/day</td></tr>
        <tr><td>Median MEAN_MOTION</td><td style="text-align:right">{mm_median} rev/day</td></tr>
        <tr><td>Median inclination</td><td style="text-align:right">{median_inc}&deg;</td></tr>
        <tr><td>Circular orbits (ecc &lt; 0.01)</td><td style="text-align:right">{ecc_ranges['Circular (< 0.01)']:,} ({round(ecc_ranges['Circular (< 0.01)']/total*100,1)}%)</td></tr>
        <tr><td>Epoch window</td><td style="text-align:right">{epoch_min} — {epoch_max}</td></tr>
      </table>
    </div>
    <div>
      <table>
        <tr><th colspan="2">Population Breakdown</th></tr>
        <tr><td>Starlink satellites</td><td style="text-align:right;font-weight:600">{starlink_count:,} ({starlink_pct}%)</td></tr>
        <tr><td>All other satellites</td><td style="text-align:right">{non_starlink:,} ({round(non_starlink/total*100,1)}%)</td></tr>
        <tr><td>LEO satellites</td><td style="text-align:right">{leo_count:,} ({leo_pct}%)</td></tr>
        <tr><td>GEO satellites</td><td style="text-align:right">{regime_counts.get('GEO',0):,} ({round(regime_counts.get('GEO',0)/total*100,1)}%)</td></tr>
        <tr><td>Launched 2020 or later</td><td style="text-align:right">{post2020:,} ({post2020_pct}%)</td></tr>
      </table>
    </div>
  </div>
</div>

<!-- ===== SECTION 2: LAUNCH TRENDS (MOST IMPORTANT) ===== -->
<div class="section" id="launch-trends">
  <h2>Launch Year Trends</h2>
  <p class="section-desc">Launch year is extracted from the first four characters of <code>OBJECT_ID</code>. This analysis covers currently active satellites only — deorbited or failed spacecraft are excluded from the catalog.</p>

  <div class="callout">
    <strong>Key Finding:</strong> The active satellite population has experienced explosive growth since 2020. Annual launches of still-active satellites surged from 151 in 2019 to 4,329 in 2025 — a 28.7x increase in just six years. The cumulative curve shifts from near-linear to exponential around 2020, coinciding with the acceleration of mega-constellation deployments.
  </div>

  <div class="chart-container">
    <h3>Cumulative Active Satellites by Launch Year (1990–2026)</h3>
    <div class="chart-wrap" style="height:400px">
      <canvas id="launchCumChart"></canvas>
    </div>
    <p class="insight">The inflection point around 2020 marks the transition from a steady ~100 satellites/year cadence to mega-constellation-scale deployment. By 2025, a single year added more satellites than the entire pre-2020 era combined.</p>
  </div>

  <div class="chart-container">
    <h3>Annual Launches of Currently Active Satellites (2015–2026)</h3>
    <div class="chart-wrap" style="height:350px">
      <canvas id="launchBarChart"></canvas>
    </div>
    <p class="insight">2026 data reflects Q1 only (962 satellites through late March), putting the year on pace to match or exceed 2025 totals. The 2020–2025 CAGR of active-satellite launches is approximately 54%.</p>
  </div>

  <div class="chart-container">
    <h3>Year-over-Year Launch Growth</h3>
    <table>
      <thead>
        <tr><th>Year</th><th style="text-align:right">Active Launches</th><th style="text-align:right">Cumulative</th><th style="text-align:right">YoY Growth</th></tr>
      </thead>
      <tbody>
        {yoy_table}
      </tbody>
    </table>
  </div>
</div>

<!-- ===== SECTION 3: CONSTELLATION ANALYSIS ===== -->
<div class="section" id="constellation-analysis">
  <h2>Major Constellation &amp; Operator Breakdown</h2>
  <p class="section-desc">Constellations are identified by parsing <code>OBJECT_NAME</code> prefixes (e.g., "STARLINK-", "ONEWEB-", "GPS"). Satellites not matching a known prefix are grouped as "Other."</p>

  <div class="callout">
    <strong>Starlink Dominance:</strong> SpaceX's Starlink constellation alone accounts for <span class="highlight">{starlink_count:,} satellites ({starlink_pct}%)</span> of all active spacecraft. It represents <span class="highlight">{starlink_leo_pct}%</span> of all LEO satellites. Excluding Starlink, the entire active catalog would total just {non_starlink:,} satellites — comparable to mid-2020 levels. This single-operator concentration has profound implications for spectrum management, debris risk, and orbital slot availability.
  </div>

  <div class="two-col">
    <div class="chart-container">
      <h3>Constellation Share (Top 10 + Other)</h3>
      <div class="chart-wrap" style="height:380px">
        <canvas id="constPieChart"></canvas>
      </div>
    </div>
    <div class="chart-container">
      <h3>Top Constellations by Count</h3>
      <div class="chart-wrap" style="height:380px">
        <canvas id="constBarChart"></canvas>
      </div>
    </div>
  </div>

  <div class="chart-container">
    <h3>Full Constellation Ranking</h3>
    <table>
      <thead>
        <tr><th>#</th><th>Constellation</th><th style="text-align:right">Count</th><th style="text-align:right">Share</th><th>Relative Scale</th></tr>
      </thead>
      <tbody>
        {const_table}
      </tbody>
    </table>
  </div>
</div>

<!-- ===== SECTION 4: ORBITAL REGIME ===== -->
<div class="section" id="orbit-regime">
  <h2>Orbital Regime Classification</h2>

  <div class="methodology">
    <strong>Classification Method (MEAN_MOTION thresholds):</strong><br>
    <strong>LEO</strong> (Low Earth Orbit): MEAN_MOTION &gt; 11.25 rev/day and eccentricity &le; 0.25 — corresponds to altitudes ~160–2,000 km<br>
    <strong>GEO</strong> (Geostationary/Geosynchronous): 0.99 &le; MEAN_MOTION &le; 1.01 rev/day and eccentricity &le; 0.25 — ~35,786 km altitude<br>
    <strong>MEO</strong> (Medium Earth Orbit): 1.01 &lt; MEAN_MOTION &le; 11.25 rev/day and eccentricity &le; 0.25 — ~2,000–35,000 km<br>
    <strong>HEO</strong> (Highly Elliptical Orbit): eccentricity &gt; 0.25 — includes Molniya, Tundra, and transfer orbits
  </div>

  <div class="two-col">
    <div class="chart-container">
      <h3>Regime Distribution</h3>
      <div class="chart-wrap" style="height:320px">
        <canvas id="regimePieChart"></canvas>
      </div>
    </div>
    <div class="chart-container">
      <h3>Regime Counts</h3>
